import { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';

interface Post {
  id: number;
  title: string;
  body: string;
}

interface Comment {
  id: number;
  name: string;
  body: string;
  email: string;
}

interface BlogPostPageProps {
  params: Promise<{
    id: string;
  }>;
}

export async function generateStaticParams() {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts')
    .then(res => res.json());

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function generateMetadata({ params }: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params;

  try {
    const post: Post = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`)
      .then(res => res.json());

    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
        type: 'article',
      },
    };
  } catch {
    return {
      title: 'Post Not Found - My Blog',
    };
  }
}

async function getPost(id: string): Promise<Post | null> {
  try {
    const post: Post = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
      next: { revalidate: 300 },
    }).then(res => res.json());
    return post;
  } catch {
    return null;
  }
}

async function getComments(id: string): Promise<Comment[]> {
  try {
    const comments: Comment[] = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
      next: { revalidate: 300 },
    }).then(res => res.json());
    return comments;
  } catch {
    return [];
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params;

  const [post, comments] = await Promise.all([
    getPost(id),
    getComments(id),
  ]);

  if (!post) {
    notFound();
  }

  return (
    <article>
      <Link href="/blog">← Back to Blog</Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

