import Link from 'next/link';

interface Post {
  id: number;
  title: string;
  userId: number;
  body: string;
}

interface HomePageProps {
  searchParams: Promise<{
    page?: string;
  }>;
}

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
    type: 'website',
  },
};

async function getUserAgent(): Promise<string> {
  // In App Router, we can get headers in Server Components
  const { headers } = await import('next/headers');
  const headersList = await headers();
  return headersList.get('user-agent') || '';
}

async function getRecentPosts(): Promise<Post[]> {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts?_limit=5', {
    cache: 'no-store',
  }).then(res => res.json());
  return posts;
}

export default async function HomePage({ searchParams }: HomePageProps) {
  const [userAgent, posts] = await Promise.all([
    getUserAgent(),
    getRecentPosts(),
  ]);
  const { page } = await searchParams;

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Your user agent: {userAgent}</p>

